export const PAPERS: PaperInput[] = [
  {"id":"2610.03120","title":"In-Distribution Forcing for Long Video Generation at Test Time","up":26,"href":"https://arxiv.org/abs/2610.03120","abstract":"Modern autoregressive (AR) video diffusion models excel at short-horizon video generation, yet generating long videos remains challenging due to drifting, where colors and textures shift, and motion dynamics decay. Existing works primarily rely on KV conditioning, which selects or modifies cached key-value (KV) entries to mitigate drifting. However, we observe that KV conditioning alone is insufficient as it assumes cached KV entries remain in-distribution. This assumption fails beyond the training horizon: nothing constrains the construction of KV entries during rollout, giving rise to the KV","pdfUrl":"https://arxiv.org/pdf/2610.03120","primaryCategory":"cs.CV","crossrefDoi":"https://doi.org/10.1109/iccv51701.2025.01735","year":2025},
  {"id":"2610.04292","title":"LMBuild: Evaluating LLM Agents for Generating Buildable and Functional Structures","up":22,"href":"https://arxiv.org/abs/2610.04292","abstract":"LLM-based agents are increasingly capable of generating complex 3D structures, with the potential to reshape how objects are designed and realized in the physical world. Yet, producing elegant geometry is fundamentally different from producing objects that can be built and perform their intended functions. Existing evaluations largely focus on geometric quality while overlooking physical realizability. We introduce LMBuild, a benchmark for evaluating LLM agents on generating buildable and functional structures. LMBuild represents generated objects as assembled structures comprising part decomp","pdfUrl":"https://arxiv.org/pdf/2610.04292","primaryCategory":"cs.AI"},
  {"id":"2609.37267","title":"Foundations of Proactive Agents: Principles, Technical Layers, and Proactivity-Gym","up":20,"href":"https://arxiv.org/abs/2609.37267","abstract":"Proactive LLM agents can turn idle compute into useful support before users ask. Yet even correct work can misread user context, impose review costs, or undermine trust. This work proposes foundations for designing, realizing, and evaluating proactive LLM agents around three joint principles (3T): Task Capability, anticipating relevant needs and correctly performing useful work; Temporal Allocation, allocating compute according to resource availability and when results are needed; and Trust, sustaining users' confidence and appropriate reliance on the agent. We connect these objectives to a de","pdfUrl":"https://arxiv.org/pdf/2609.37267","primaryCategory":"cs.AI"},
  {"id":"2610.05076","title":"Self-Generated Feedback Destabilizes Test-Time Training: A Causal Decomposition of Long-Horizon Adaptation","up":18,"href":"https://arxiv.org/abs/2610.05076","abstract":"Test-time training (TTT) lets a model store information in its weights during inference. When the model learns from its own output, however, each update also changes the model that generates the next training example. Across 128K-token streams, retaining generated-text updates worsens prediction on independent human-written text with three TTT-E2E model configurations (labeled 125M, 760M, and 3B). The same failure occurs when Adam updates Qwen3-4B's existing weights. The same update mechanisms can improve on real text, so writing itself is not the failure. Three matched comparisons trace the c","pdfUrl":"https://arxiv.org/pdf/2610.05076","primaryCategory":"cs.CL"},
  {"id":"2610.06577","title":"Optimizing the Optimizer: Language Models Discover Faster Molecular Relaxation","up":15,"href":"https://arxiv.org/abs/2610.06577","abstract":"Geometry optimization is a major cost in many quantum-chemical workflows: each optimization step requires one force evaluation, and at the density-functional level that evaluation dominates the wall time. Research in this area has produced a broad range of optimization methods, and we ask whether a language model can improve on the best of them through autoresearch. An agent rewrites the optimizer itself to minimize force-call counts, restrained by two admission gates that reject premature stopping and improvements that do not generalize to unseen molecules. Starting from Sella, the fastest op","pdfUrl":"https://arxiv.org/pdf/2610.06577","primaryCategory":"physics.chem-ph"},
  {"id":"2609.36099","title":"Data Unlearning via Inverse Distillation","up":14,"href":"https://arxiv.org/abs/2609.36099","abstract":"Multi-step matching models, including flow and diffusion models, produce high-quality outputs but incur substantial inference costs and may reproduce unwanted components of their training datasets. We introduce Inverse Distillation Unlearning (IDU), a unified framework that simultaneously distills a teacher multi-step matching model into an efficient one-step student generator and suppresses outputs corresponding to a designated training subset. We first formulate distillation as a min-max objective over a data distribution and then represent this distribution as a mixture of the forget-set an","pdfUrl":"https://arxiv.org/pdf/2609.36099","primaryCategory":"cs.LG"},
  {"id":"2610.06648","title":"Representation-Space MMD for Diffusion Language Models","up":14,"href":"https://arxiv.org/abs/2610.06648","abstract":"We introduce a post-training method for diffusion language models (DLMs) that minimizes Maximum Mean Discrepancy (MMD) between generated and reference distributions in the feature space of a frozen pretrained DLM. To estimate MMD, we retain contextual features at individual token positions, obtaining multiple observations per sequence from a single extractor pass. We optimize this objective using policy gradients for discrete models and direct differentiation through generated latents for continuous models. In both cases, computing the loss directly from these features enables efficient post-t","pdfUrl":"https://arxiv.org/pdf/2610.06648","primaryCategory":"cs.CL"},
  {"id":"2610.05107","title":"SearchJev: A Fast and Calibrated System-1 Model for Search Agents","up":13,"href":"https://arxiv.org/abs/2610.05107","abstract":"Search agents repeatedly make short decisions about relevance, evidence sufficiency, and search actions. Using generative language models for these decisions introduces latency and unreliable confidence. We present SearchJev, a fast and calibrated System-1 model that separates search decisions from System-2 reasoning and generation. Given a search state and a decision schema, SearchJev directly scores legal options without autoregressive output generation. We propose Soft-Label Learning for Calibrated Decisions (SLCD) to learn decision probabilities from uncertain supervision and calibrate the","pdfUrl":"https://arxiv.org/pdf/2610.05107","primaryCategory":"cs.IR"},
  {"id":"2609.39490","title":"OmniReasoning: Pushing the Limits of Audio-Visual Joint Reasoning","up":12,"href":"https://arxiv.org/abs/2609.39490","abstract":"Recent advances have enabled unified omni-modal models in understanding audio, vision, and language. However, existing benchmarks, training data, and learning methods largely treat the modalities independently, leaving the capability of audio-visual joint reasoning poorly evaluated and insufficiently elicited. We address this gap with a benchmark, data engine, and learning method. First, we introduce OmniReasoningBench, a benchmark where both audio and visual evidence are indispensable. It comprises 1,150 multiple-choice and open-ended questions across two tasks, reasoning over video and reaso","pdfUrl":"https://arxiv.org/pdf/2609.39490","primaryCategory":"cs.CV"},
  {"id":"2610.04929","title":"RobotUse: Allocating Computation, Context, and Decisions","up":11,"href":"https://arxiv.org/abs/2610.04929","abstract":"Robot agents must connect their intended actions to observed outcomes while retaining the context needed to revise their choices over repeated attempts. Existing interfaces often leave these choices inside predefined tools or require agents to manage detailed execution code and its growing history. We introduce RobotUse, a robot agent harness that organizes computation, context, and decisions around specifying and revising physical actions. Agents visually select targets and poses, while the backend handles geometry, motion planning, and control. Subagents retain detailed interactions within e","pdfUrl":"https://arxiv.org/pdf/2610.04929","primaryCategory":"cs.RO"},
  {"id":"2609.36691","title":"Video2Skill: From Streaming Experience to Reusable Embodied Skills","up":8,"href":"https://arxiv.org/abs/2609.36691","abstract":"Manipulation behaviors vary widely across objects and scenes, but they share a small set of reusable skills, and planning with these skills helps embodied agents generalize to new tasks. Yet an agent can only plan with skills it knows. Recovering skills from observed experience, the inverse of planning, builds this knowledge over time and yields skill data for training future agents. Vision-Language Models (VLMs) describe individual manipulation events well, but can they organize a stream of events into reusable skills? We formulate this problem as Streaming Embodied Skill Discovery (SESD): a ","pdfUrl":"https://arxiv.org/pdf/2609.36691","primaryCategory":"cs.CL"},
  {"id":"2609.36684","title":"ProgressCompass: Embodied Progress Reward Models Are Lost Without the Right Context","up":7,"href":"https://arxiv.org/abs/2609.36684","abstract":"Embodied agents now take on ever longer tasks. For long tasks, knowing only whether a task finally succeeds or fails says little; the steps along the way matter. Progress Reward Models (PRMs) score how far a task has come at every step, and serve as dense rewards, verifiers and monitors. Yet in long tasks the current frame alone often cannot tell how far the task has come, because progress depends on what happened before. We call this problem context-dependent progress estimation. Existing benchmarks on progress estimation mostly focus on short tasks whose progress can be read from the current","pdfUrl":"https://arxiv.org/pdf/2609.36684","primaryCategory":"cs.CL"},
  {"id":"2610.04616","title":"PerturBot: Breaking Shortcut Priors in Vision-Language-Action Models with Perturbative Training","up":7,"href":"https://arxiv.org/abs/2610.04616","abstract":"A vision--language--action (VLA) policy can complete complex tasks while ignoring the evidence that should determine its actions. An object held near the wrist camera can displace the instructed target. Language and action show the same pattern: a familiar noun can trigger the operation it was paired with in training even after the verb changes, and a gripper that closed on nothing may lift anyway. We call these dependencies modality shortcuts: regularities in successful demonstrations make visual, lexical, or motor cues sufficient to predict expert actions without the task evidence needed for","pdfUrl":"https://arxiv.org/pdf/2610.04616","primaryCategory":"cs.RO"},
  {"id":"2610.05622","title":"UndoBench: Separating Task Competence from Recovery Capability in Tool-Using AI Agents","up":7,"href":"https://arxiv.org/abs/2610.05622","abstract":"Tool-using AI agents are increasingly deployed across enterprise software systems, yet widely used benchmarks primarily evaluate nominal task completion, conflating baseline planning competence with operational fault recovery. We introduce UndoBench, a benchmark spanning 36 base workflows and 36 fault scenarios across 8 enterprise domains, decoupling task competence from recovery capability via counterfactual paired trials under identical seeds alongside wire-level effect-history and environment-state oracles. On 12 held-out TEST workflows across two open-weight models, two frameworks, and thr","pdfUrl":"https://arxiv.org/pdf/2610.05622","primaryCategory":"cs.SE"},
  {"id":"2609.39420","title":"QuantCode Model: Specializing Language Models for Executable Algorithmic Trading Code","up":6,"href":"https://arxiv.org/abs/2609.39420","abstract":"Large language models are strong general-purpose code generators, but executable algorithmic trading remains a demanding specialization target: a model must translate a natural-language strategy specification into correct program logic for a specialized trading framework, execute on historical data, produce trades, and remain semantically faithful to the request. We study two complementary mechanisms for specializing language models for this setting: continued pretraining on algorithmic-trading framework code and supervised fine-tuning (SFT) on agent-validated request-to-code pairs. Evaluation","pdfUrl":"https://arxiv.org/pdf/2609.39420","primaryCategory":"cs.CL"},
  {"id":"2610.02331","title":"World Editing: Intervening on Executable Worlds at Increasing Depth","up":6,"href":"https://arxiv.org/abs/2610.02331","abstract":"Interactive world models are increasingly capable of generating environments and acting within them, yet deliberately editing an existing executable world remains underexplored. We formulate world editing as intervening on an existing world while preserving properties that should remain unchanged, and introduce intervention depth as an axis describing how strongly an edit couples world entities, dynamics, and systems. We instantiate this capability through industry-grade game modding and introduce IGMWorld, together with IGMBench, a benchmark of 110 tasks and over 1.1K executable state and beh","pdfUrl":"https://arxiv.org/pdf/2610.02331","primaryCategory":"cs.AI"},
  {"id":"2609.35751","title":"How to Loop MoE: Flatten the Experts, Untie the Attention","up":5,"href":"https://arxiv.org/abs/2609.35751","abstract":"Looped Transformers reuse one block of layers several times: by spending extra computation they push a model of fixed size further, and so use its parameters more fully; while sparse mixture-of-experts (MoE) models activate only a few of many experts for each token. Looped MoE bridges these two design philosophies and gives MoE models new potential for better expert usage, but it raises a question: how to loop a MoE? We answer it with Foil. With the expert parameters and the expert compute per token held fixed, Foil (1) flattens the experts, halving the expert layers, doubling the experts per ","pdfUrl":"https://arxiv.org/pdf/2609.35751","primaryCategory":"cs.LG"},
  {"id":"2610.02150","title":"From Knowledge Access to Source Learning: Developing Source-Specific Competence","up":5,"href":"https://arxiv.org/abs/2610.02150","abstract":"Large language model (LLM) agents increasingly rely on persistent external sources to solve sequences of knowledge-intensive tasks. Existing methods improve how source content is accessed and organized, while agent-memory systems preserve reusable knowledge from prior interactions, but repeated use of the same source is still largely treated as repeated access rather than an opportunity to progressively improve understanding of that source. We study source learning: developing reusable source-specific competence over a persistent authoritative source. We represent this competence with a persis","pdfUrl":"https://arxiv.org/pdf/2610.02150","primaryCategory":"cs.CL"},
  {"id":"2610.02320","title":"DeskForge: Dense Supervision from Desktop Environments for Computer-Use Agents","up":5,"href":"https://arxiv.org/abs/2610.02320","abstract":"Computer-use agents need to reliably ground action targets in complex desktop scenes, where multiple applications, overlapping windows, and visually similar controls compete for attention. Existing training data rarely pair such scenes with dense annotations or vary them in a controlled way. We introduce DeskForge, a controllable desktop environment that composes and explores real applications to generate large-scale supervision for computer-use agents. It varies application states, content, window layout, appearance, and resolution, and fuses screenshots, accessibility trees, and window geome","pdfUrl":"https://arxiv.org/pdf/2610.02320","primaryCategory":"cs.CV"},
  {"id":"2610.04128","title":"What Gradients Add to Text Leakage in Split Language Models, Counted per Token and per Document","up":5,"href":"https://arxiv.org/abs/2610.04128","abstract":"Split learning lets a client train a language model on a server without sending its text. The client runs the first layers itself and sends the server only their output, a vector of numbers for each token. During training, the server sends gradients back. We show that an observer at the split can rebuild most of the client's text from this traffic, and we measure how much the gradients help. On GPT-2, an attacker who holds only the publicly released weights of the client's layers recovers 94.20% of tokens from the activations alone and 97.38% when it also sees the gradients, 3.17 percentage po","pdfUrl":"https://arxiv.org/pdf/2610.04128","primaryCategory":"cs.CR"},
  {"id":"2610.05538","title":"LiFT: Loop Flow Transformers","up":5,"href":"https://arxiv.org/abs/2610.05538","abstract":"We introduce Loop Flow Transformers (LiFT), a family of looped generative models that scales computation by repeatedly applying a shared Diffusion Transformer (DiT) core, with only light changes to the standard architecture. Rather than asking every recurrent step for the final prediction, LiFT trains each step with a single regression target: a point on a straight path from the model's initial estimate to the flow-matching target. Because we index these targets by a continuous depth coordinate, a trained model can loop far beyond its training depth with no retraining, early exits, or other mo","pdfUrl":"https://arxiv.org/pdf/2610.05538","primaryCategory":"cs.LG"},
  {"id":"2610.06666","title":"What Matters for Latent Reasoning with Flow Matching","up":5,"href":"https://arxiv.org/abs/2610.06666","abstract":"Latent reasoning lets a large language model (LLM) think in a continuous space and verbalize only the answer. We argue that an effective latent thought must meet five requirements: it should be useful, helping produce the correct answer rather than merely changing it, diverse, so that resampling yields different reasoning trajectories, explainable, so that a decoded chain of thought (CoT) reflects reasoning the answer actually follows, refinable with more inference compute, and efficient, costing less than an explicit CoT at comparable accuracy. Current methods rarely meet these requirements: ","pdfUrl":"https://arxiv.org/pdf/2610.06666","primaryCategory":"cs.LG"},
  {"id":"2610.04047","title":"Periscope: Extending Frozen Language Models Beyond Their Context Window","up":4,"href":"https://arxiv.org/abs/2610.04047","abstract":"A language model reads long text in one quadratic forward pass, stops at the context window, and loses accuracy with length before reaching it. We ask whether the read can be factorized when deciding over a finite set: which document is relevant, which option is supported, which passage is the evidence. Periscope, a training-free inference method, arranges the $N$ chunks of a text on a $K{\\times}K$ grid with $K{=}\\lceil\\sqrt{N}\\rceil$ and asks a frozen model the same question about $K$ local spans of consecutive chunks and $K$ strided spans that sample the whole text, reading the log-odds of e","pdfUrl":"https://arxiv.org/pdf/2610.04047","primaryCategory":"cs.CL"},
  {"id":"2610.05879","title":"Learning to Learn a Language","up":4,"href":"https://arxiv.org/abs/2610.05879","abstract":"We present the Prior-Fitted Language Model (PFLM), a 300M-parameter byte-level transformer pretrained only on samples from a synthetic non-linguistic prior. Given a prefix of real text, it learns to predict the language in context with frozen weights, having never seen a word of any real language. Every training sequence is generated by a recurrent structural causal model drawn fresh from a distribution over such models. The model never sees the same language twice during training, so the only way to predict the continuation is to infer the language from the prefix. Samples from this prior sha","pdfUrl":"https://arxiv.org/pdf/2610.05879","primaryCategory":"cs.CL"},
];

